<script setup lang="ts">
import AppButton from './AppButton.vue'
import {reactive,ref,watch,computed,onMounted} from 'vue'
import {FolderOpen,KeyRound,Monitor,Save} from '@lucide/vue'
import {notify} from '../notifications'
import type {Config,GeminiConnection} from '../types'
const props=defineProps<{config:Config;saveConfig:(value:Config)=>Promise<unknown>;saveKey:(value:string)=>Promise<unknown>;pick:(kind:string)=>Promise<string|null>;getConnection?:()=>Promise<GeminiConnection>;testConnection?:()=>Promise<GeminiConnection>}>()
const values=reactive({clip_preferred_seconds:60,clip_max_seconds:180,pause_mode:'conservative' as const,show_thought_summaries:true,...props.config}),key=ref(''),busy=ref(false)
const connection=ref<GeminiConnection|null>(null),validating=ref(false)
const statusLabel=computed(()=>validating.value?'Validando…':connection.value?.status==='valid'?'Conexão validada':connection.value?.status==='invalid'?'Chave sem acesso':connection.value?.status==='unavailable'?'Conexão indisponível':props.config.gemini_key_configured?'Chave salva · não testada':'Chave não configurada')
const models=computed(()=>connection.value?.models||[])
const listed=computed(()=>models.value.some(m=>m.id===values.gemini_model))
const missingModel=computed(()=>connection.value?.status==='valid'&&!listed.value)
watch(()=>props.config,(value,old)=>{for(const field of Object.keys(value) as (keyof Config)[]){if(value[field]!==old[field])Object.assign(values,{[field]:value[field]})}},{deep:true})
onMounted(async()=>{if(props.getConnection)try{connection.value=await props.getConnection()}catch(e){notify.error((e as Error).message)}})
async function execute(fn:()=>Promise<unknown>,success:string){busy.value=true;try{await fn();if(success)notify.success(success)}catch(e){notify.error((e as Error).message)}finally{busy.value=false}}
async function saveKey(){validating.value=true;await execute(async()=>{const result=await props.saveKey(key.value);if(result)connection.value=result as GeminiConnection;key.value='';if(!result||connection.value?.status==='valid')notify.success(result?'Conexão validada. Chave armazenada no Windows.':'Chave armazenada no Windows.');else notify.error(connection.value?.message||'Não foi possível validar a conexão.')},'');validating.value=false}
async function testConnection(){if(!props.testConnection)return;validating.value=true;await execute(async()=>{connection.value=await props.testConnection!();if(connection.value.status==='valid')notify.success('Conexão Gemini validada. Catálogo atualizado.');else notify.error(connection.value.message)},'');validating.value=false}
async function saveSettings(){if(values.clip_preferred_seconds>values.clip_max_seconds){notify.error('A duração preferida deve ser menor ou igual à máxima.');return}if(!missingModel.value)await execute(()=>props.saveConfig({...values}),'Configurações salvas.')}
async function pick(kind:string,field:'asr_model_path'|'ffmpeg'|'ffprobe'){await execute(async()=>{const result=await props.pick(kind);if(result)values[field]=result},'')}
</script>
<template>
  <header class="page-heading"><div><p class="breadcrumb">Preferências do aplicativo</p><h1>Configurações</h1><p>Seu processamento local. Seu modelo de análise.</p></div></header>
  <ol class="configuration-steps"><li><b>01</b>Recursos locais</li><li><b>02</b>Chave e conexão Gemini</li><li><b>03</b>Modelo e preferências</li></ol><div class="settings-grid">
    <form class="settings-main" @submit.prevent="saveSettings">
      <section class="setting-section"><h2><Monitor :size="19"/>Processamento local</h2><p>Transcrição e renderização usam a CPU. Escolha os recursos já instalados.</p><div class="readiness-items"><span>{{config.asr_available?'Modelo local disponível':'Modelo local não encontrado'}}</span><span>{{config.tools_available?'FFmpeg e ffprobe disponíveis':'Ferramentas não encontradas'}}</span></div><label class="field">Pasta do modelo Whisper<span class="input-action"><input v-model="values.asr_model_path" required/><AppButton type="button" class="icon-button" title="Escolher pasta do modelo" @click="pick('model','asr_model_path')"><FolderOpen :size="18"/></AppButton></span><small>Modelo multilíngue com suporte ao português; arquivos ficam locais.</small></label><div class="field-pair"><label class="field">FFmpeg<span class="input-action"><input v-model="values.ffmpeg" required/><AppButton type="button" class="icon-button" title="Localizar FFmpeg" @click="pick('ffmpeg','ffmpeg')"><FolderOpen :size="17"/></AppButton></span></label><label class="field">ffprobe<span class="input-action"><input v-model="values.ffprobe" required/><AppButton type="button" class="icon-button" title="Localizar ffprobe" @click="pick('ffprobe','ffprobe')"><FolderOpen :size="17"/></AppButton></span></label></div></section>
<section class="credential-panel"><div class="section-icon"><KeyRound :size="22"/></div><h2>Chave Gemini</h2><span class="status-pill" :data-status="validating?'running':connection?.status==='valid'?'completed':'pending'"><i></i>{{statusLabel}}</span><AppButton v-if="connection?.status==='invalid'||connection?.status==='unavailable'" type="button" class="text-button" @click="notify.error(connection!.message)">Ver motivo da falha</AppButton><p>Armazenada no Gerenciador de Credenciais do Windows. O aplicativo não exibe a chave salva.</p><label class="field">{{config.gemini_key_configured?'Substituir chave':'Adicionar chave'}}<input type="password" @keydown.enter.prevent="!busy&&key.trim()&&saveKey()" v-model="key" autocomplete="new-password" placeholder="Cole sua chave de API"/></label><AppButton type="button" class="button secondary full" data-action="save-key" :disabled="busy||!key.trim()" @click="saveKey"><KeyRound :size="16"/>{{validating?'Validando…':'Salvar e validar'}}</AppButton><AppButton type="button" class="button secondary full" data-action="test-gemini" :disabled="busy||!config.gemini_key_configured" @click="testConnection">{{validating?'Validando…':'Testar conexão / Atualizar modelos'}}</AppButton><p v-if="connection?.checked_at">Último teste: {{new Date(connection.checked_at).toLocaleString('pt-BR')}}</p><p>O teste consulta apenas o catálogo. Não gera conteúdo nem verifica a cota de geração.</p></section>
      <section class="setting-section"><h2>Seleção de trechos</h2><p>Projetos novos seguem da transcrição para a análise com Gemini automaticamente. O motor dimensiona as chamadas pelo conteúdo.</p><label class="field">Modelo Gemini<select v-model="values.gemini_model" data-field="gemini-model" required :disabled="busy||!models.length"><option v-if="!listed" :value="values.gemini_model" disabled>{{values.gemini_model}} — {{missingModel?'não aparece no catálogo':'modelo salvo'}}</option><option v-for="model in models" :key="model.id" :value="model.id">{{model.display_name}} · {{model.id}}</option></select><small v-if="missingModel">O modelo salvo não aparece no catálogo. Escolha outro modelo explicitamente.</small><small v-else>{{models.length?models.length+' modelos disponíveis.':'Teste a conexão para carregar os modelos disponíveis.'}}</small></label><details class="analysis-advanced"><summary>Ajustes avançados de análise</summary><p>Você pode manter os padrões. A janela define quanto tempo da transcrição é analisado por vez; o limite de caracteres divide textos muito grandes. Esses valores não definem a duração dos cortes.</p><div class="field-pair"><label class="field">Janela de análise (segundos)<input type="number" v-model.number="values.window_seconds" min="60" max="1800" required/></label></div><label class="field">Máximo de caracteres por janela<input type="number" v-model.number="values.max_text_chars" min="1000" max="300000" required/><small>Limite aproximado do texto e identificadores por solicitação; não é um limite de tokens do modelo.</small></label></details></section>
      <section class="setting-section"><h2>Coerência, duração e pausas</h2><p>Prefira cortes curtos, permitindo mais tempo para concluir o argumento. Configurações valem para os próximos trabalhos.</p><div class="field-pair"><label class="field">Duração preferida (segundos)<input type="number" data-field="clip-preferred" v-model.number="values.clip_preferred_seconds" min="20" max="180" required/><small>Uma preferência; não força encerrar o raciocínio.</small></label><label class="field">Duração máxima (segundos)<input type="number" data-field="clip-max" v-model.number="values.clip_max_seconds" min="20" max="180" required/><small>Até 180 segundos (3 minutos). Não recorta palavras para caber.</small></label></div><label class="field">Pausas entre falas<select data-field="pause-mode" v-model="values.pause_mode"><option value="preserve">Preservar todas as pausas</option><option value="conservative">Encurtar silêncios longos com verificação no áudio</option></select><small>Detecção de voz e volume, com margens de proteção. Respirações curtas permanecem. Confira as junções na revisão.</small></label><label class="check-row"><input type="checkbox" data-field="thought-summaries" v-model="values.show_thought_summaries"/><span>Mostrar resumos de análise enviados pelo Gemini</span></label><p class="subtle">Disponibilidade depende do modelo e da API. Resumos não mostram o pensamento interno completo. Modelos com pensamento habilitado podem consumir mais tokens.</p></section>
      <div class="setting-save"><AppButton class="button primary" data-action="save-config" :disabled="busy||missingModel"><Save :size="16"/>Salvar configurações</AppButton></div>
    </form>

  </div>
</template>
